def run_agent(model, tools, goal, max_steps=6):
    state = {"goal": goal, "events": []}
    for step in range(max_steps):
        action = model.next_action(state)
        if action["type"] == "finish":
            return {"status": "completed", "answer": action["answer"], "state": state}
        if action["tool"] not in tools:
            state["events"].append({"error": "unknown_tool", "action": action})
            continue
