    fingerprint = repr(sorted(arguments.items()))
    prior = store.get(key)
    if prior:
        if prior["fingerprint"] != fingerprint:
            raise ValueError("idempotency_key_conflict")
        return prior["result"]
    result = operation(**arguments)
    store[key] = {"fingerprint": fingerprint, "result": result}
    return result

