def fuse_confidence(observations, reliability):
    weighted, total, values = 0.0, 0.0, []
    for modality, score in observations.items():
        weight = reliability.get(modality, 0.0)
        if score is None or weight <= 0:
            continue
        weighted += score * weight; total += weight; values.append(score)
    if not values:
        return {"confidence": None, "disagreement": None}
    return {"confidence": weighted/total, "disagreement": max(values)-min(values)}

